        perPage?: number,
        /**
         * filter by path
         */
        path?: string,
        isFlow?: boolean,
        pathStart?: string,
    }): CancelablePromise<Array<PostgresTrigger>> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/w/{workspace}/postgres_triggers/list',
